def f(g):
    H,W=len(g),len(g[0])
    seen=set(); objs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==col and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                obj=[[0]*(max(cs)-min(cs)+1) for _ in range(max(rs)-min(rs)+1)]
                for a,b in cells: obj[a-min(rs)][b-min(cs)]=col
                objs.append((min(cs),obj))
    objs.sort(key=lambda x:x[0])
    max_h=max(len(o) for _,o in objs)
    tot_w=sum(len(o[0]) for _,o in objs)
    out=[[0]*tot_w for _ in range(max_h)]
    cur=0
    for _,o in objs:
        for i,row in enumerate(o):
            for j,x in enumerate(row): out[i][cur+j]=x
        cur+=len(o[0])
    return out
